const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const keys=['control','moves','yard'],titles=['Controle de prancha','Movimentações do sistema','Patiamento da empresa'],colors=['#de8554','#5195a8','#58a582','#aab7bf'],statuses=['MANUTENÇÃO','EM USO','DISPONÍVEL PARA USO','SEM INFORMAÇÃO'];let loaded={},results=[],counts=[0,0,0,0],worker=new Worker('worker.js'),busy=new Set();
$('#uploads').innerHTML=keys.map((k,i)=>`<div class="upload" data-key="${k}"><label><div class="icon">${['▤','⇄','▥'][i]}</div><h3>${i+1}. ${titles[i]}</h3><p>Arraste aqui ou selecione um arquivo</p><input type="file" accept=".xlsx,.xls,.csv" data-key="${k}" aria-label="${titles[i]}"></label><p id="file-${k}" class="filename">Nenhum arquivo selecionado</p><select id="sheet-${k}" aria-label="Aba de ${titles[i]}" hidden></select><p id="status-${k}"></p></div>`).join('');
function ready(){ $('#process').disabled=!keys.every(k=>loaded[k])||busy.size>0;$('#export').disabled=!results.length; }
function invalidate(){results=[];$('#export').disabled=true;$('#rows').innerHTML='<tr><td colspan="5" class="empty">Arquivos alterados. Cruze os dados para atualizar o resultado.</td></tr>';counts=[0,0,0,0];$('#pending').hidden=true;$('#count').textContent='';$('#quality').textContent='Aguardando novo cruzamento';draw();metrics();}
async function load(k,f){if(!f)return;if(!/\.(xlsx|xls|csv)$/i.test(f.name)){message('Selecione um arquivo Excel ou CSV.');return}if(f.size>60*1024*1024){message('Limite de 60 MB por arquivo.');return}busy.add(k);delete loaded[k];invalidate();ready();$('#file-'+k).textContent=f.name;$('#status-'+k).textContent='Lendo arquivo…';try{const buffer=await f.arrayBuffer();worker.postMessage({type:'load',key:k,buffer},[buffer])}catch(e){busy.delete(k);message(e.message);ready()}}
function message(t){$('#message').textContent=t}
keys.forEach(k=>{let area=$(`[data-key="${k}"]`);area.addEventListener('dragover',e=>{e.preventDefault();area.classList.add('over')});area.addEventListener('dragleave',()=>area.classList.remove('over'));area.addEventListener('drop',e=>{e.preventDefault();area.classList.remove('over');load(k,e.dataTransfer.files[0])});area.querySelector('input').onchange=e=>load(k,e.target.files[0]);$('#sheet-'+k).onchange=e=>parse(k,e.target.value)});
function parse(k,sheet){busy.add(k);delete loaded[k];invalidate();ready();$('#status-'+k).textContent='Analisando aba…';worker.postMessage({type:'parse',key:k,sheet})}
worker.onmessage=({data:d})=>{let k=d.key;if(d.type==='sheets'){let s=$('#sheet-'+k);s.hidden=false;s.innerHTML=d.names.map(n=>`<option>${esc(n)}</option>`).join('');s.value=d.names.find(n=>k==='moves'?/MOV/i.test(n):k==='yard'?Engine.norm(n)==='PRANCHAS':/CONTROLE DE FROTA|PRANCHAS|CONTROLE DE PRANCHA/i.test(n))||d.names[0];parse(k,s.value)}if(d.type==='parsed'){loaded[k]=d.result;busy.delete(k);$('#status-'+k).textContent=`${d.result.items.length} registros válidos · ${d.result.invalid} linhas sem frota válida`;message(keys.every(x=>loaded[x])?'Tudo pronto. Clique em Cruzar dados.':'Adicione os arquivos restantes.');ready()}if(d.type==='error'){busy.delete(k);$('#status-'+k).textContent=d.message;message('Confira a aba selecionada.');ready()}};worker.onerror=()=>{busy.clear();message('Não foi possível processar o arquivo. Recarregue a página e tente novamente.');ready()};
$('#process').onclick=()=>{results=Engine.reconcile(loaded.control,loaded.moves,loaded.yard);counts=statuses.map(s=>results.filter(r=>r.status===s).length);metrics();draw();render();renderPending();$('#quality').textContent=results.filter(r=>r.notes).length+' frotas com alertas para conferência';message('Cruzamento concluído · 185 frotas organizadas.');ready()};
function metrics(){$('#metrics').innerHTML=statuses.map((s,i)=>`<div class="metric" style="--color:${colors[i]}"><label>${s}</label><div class="num">${results.length?counts[i]:'—'}</div><small>${results.length?(counts[i]/185*100).toFixed(1).replace('.',',')+'% da frota':'Aguardando dados'}</small></div>`).join('')}
function draw(){let c=$('#chart'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);let total=counts.reduce((a,b)=>a+b,0),angle=-Math.PI/2;counts.forEach((n,i)=>{if(!n)return;let end=angle+n/(total||1)*Math.PI*2;ctx.beginPath();ctx.moveTo(220,150);ctx.arc(220,150,116,angle,end);ctx.closePath();ctx.fillStyle=colors[i];ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=4;ctx.stroke();angle=end});if(!total){ctx.beginPath();ctx.arc(220,150,116,0,Math.PI*2);ctx.fillStyle='#e8eef1';ctx.fill()}$('#legend').innerHTML=statuses.map((s,i)=>`<div class="legenditem"><i style="background:${colors[i]}"></i>${s}<br><strong>${total?counts[i]:'—'}</strong> <span>· ${total?(counts[i]/185*100).toFixed(1).replace('.',','):'0'}%</span></div>`).join('')}
function fmt(t){return t?new Date(t).toLocaleString('pt-BR',{timeZone:'UTC',dateStyle:'short',timeStyle:'short'}):'—'}
function render(){let q=Engine.norm($('#search').value),filter=$('#filter').value,rows=results.filter(r=>(filter==='review'?!!r.notes:!filter||r.status===filter)&&Engine.norm(Object.values(r).join(' ')).includes(q));$('#count').textContent=`· ${rows.length} de 185`;$('#rows').innerHTML=rows.map(r=>{let i=statuses.indexOf(r.status);return `<tr><td><strong>${r.frota}</strong><small>${esc(r.plate||'Sem cadastro')}</small></td><td><span class="badge" style="--bg:${colors[i]}20;--fg:${colors[i]}">${r.status}</span></td><td>${esc(r.client||r.local)}<small>${esc(r.client?r.local:'Cliente não informado')} · ${esc(r.capacity)}</small></td><td>${fmt(r.time)}<small>${esc(r.stage)} · ${esc(r.dest)}</small></td><td><button class="${r.notes?'review':'view'}" data-id="${r.id}">${r.notes?'⚑ Conferir':'Ver detalhes'} ↗</button></td></tr>`}).join('')||'<tr><td colspan="5" class="empty">Nenhuma frota encontrada para este filtro.</td></tr>'}
$('#search').oninput=render;$('#filter').onchange=render;$('#rows').onclick=e=>{let b=e.target.closest('[data-id]');if(!b)return;let r=results.find(r=>r.id===+b.dataset.id);$('#detailbody').innerHTML=`<h2>${r.frota}</h2><h3>${r.status}</h3>`+Object.entries({'Cliente':r.client,'Local':r.local,'Motivo':r.reason,'Movimentação':fmt(r.time),'Destino':r.dest,'Entrada no pátio':fmt(r.entry),'Saída do pátio':fmt(r.exit),'Capacidade de peso':r.capacity,'Cor do patiamento':r.color,'Última etapa':r.stage,'Observação do pátio':r.obs,'Fonte':r.source,'Fonte do pátio':r.yardSource,'Alertas':r.notes||'Nenhum'}).map(([k,v])=>`<p><b>${k}</b><br>${esc(v||'—')}</p>`).join('');$('#detail').showModal()};$('#close').onclick=()=>$('#detail').close();
function chartImage(){let c=document.createElement('canvas');c.width=1100;c.height=540;let x=c.getContext('2d');x.fillStyle='white';x.fillRect(0,0,1100,540);x.fillStyle='#153643';x.font='bold 28px Arial';x.fillText('Distribuição das 185 pranchas',35,48);x.drawImage($('#chart'),0,75,560,380);statuses.forEach((s,i)=>{x.fillStyle=colors[i];x.fillRect(570,130+i*75,16,16);x.font='bold 18px Arial';x.fillStyle='#153643';x.fillText(s,605,145+i*75);x.font='16px Arial';x.fillText(`${counts[i]} pranchas · ${(counts[i]/185*100).toFixed(1)}%`,605,170+i*75)});return c.toDataURL('image/png')}
$('#export').onclick=async()=>{let b=$('#export');b.disabled=true;b.textContent='Gerando Excel…';try{let bytes=await exportControl(results,loaded.yard.pending||[],keys.map(k=>`${titles[keys.indexOf(k)]}: ${$('#file-'+k).textContent} | Aba: ${$('#sheet-'+k).value}`));let url=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})),a=document.createElement('a');a.href=url;a.download='CONTROLE_PRANCHAS_'+new Date().toISOString().slice(0,10)+'.xlsx';a.textContent='Baixar Excel gerado';a.className='download-ready';document.querySelector('.download-ready')?.remove();document.querySelector('.actionrow').append(a);a.click();message('Excel exportado no modelo original, com gráfico pizza editável e pendências.')}catch(e){message('Erro ao exportar: '+e.message)}finally{b.textContent='↓ Exportar Excel';ready()}};
metrics();draw();

function renderPending(){let p=loaded.yard?.pending||[],n=p.filter(x=>x.maintenance).length;$('#pending').innerHTML=`<h2>Conferência do patiamento</h2><p><b>${counts[0]+n} registros ativos de manutenção: ${counts[0]} frotas identificadas + ${n} sem número de frota.</b> O gráfico considera somente as 185 frotas identificáveis.</p><p>Verde: disponível e aguenta peso. Cinza: disponível, mas não aguenta peso. Vermelho: manutenção.</p>${p.length?'<table><thead><tr><th>ABA / LINHA</th><th>STATUS</th><th>OBSERVAÇÃO</th><th>PENDÊNCIA</th></tr></thead><tbody>'+p.map(x=>`<tr><td>${esc(x.sheet)} · ${x.row}</td><td>${x.maintenance?'MANUTENÇÃO':esc(x.color)}</td><td>${esc(x.obs)}</td><td>Preencher número da frota na planilha de origem</td></tr>`).join('')+'</tbody></table>':''}`;$('#pending').hidden=false}
